}

test_suite:
test('returns initial values', () => {
  const { result } = renderHook(() => useReducerForm({ name: '', age: 0 }));
  expect(result.current.values).toEqual({ name: '', age: 0 });
});

test('setField updates one field', () => {
  const { result } = renderHook(() => useReducerForm({ name: '', age: 0 }));
  act(() => result.current.setField('name', 'Alice'));
  expect(result.current.values.name).toBe('Alice');
  expect(result.current.values.age).toBe(0);
});

test('multiple setField calls are independent', () => {
  const { result } = renderHook(() => useReducerForm({ a: 1, b: 2, c: 3 }));
  act(() => result.current.setField('a', 10));
  act(() => result.current.setField('c', 30));
  expect(result.current.values).toEqual({ a: 10, b: 2, c: 30 });
});

test('reset restores initial values', () => {
  const { result } = renderHook(() => useReducerForm({ name: 'Bob', score: 5 }));
  act(() => result.current.setField('name', 'Alice'));
  act(() => result.current.setField('score', 99));
  act(() => result.current.reset());
  expect(result.current.values).toEqual({ name: 'Bob', score: 5 });
});

// __hidden__
test('setField does not mutate other fields after reset', () => {
  const { result } = renderHook(() => useReducerForm({ x: 0, y: 0 }));
  act(() => result.current.setField('x', 5));
  act(() => result.current.reset());
  act(() => result.current.setField('y', 7));
  expect(result.current.values.x).toBe(0);
  expect(result.current.values.y).toBe(7);
});

solution:
import { useReducer } from 'react';

type Action<T> =
  | { type: 'set'; key: keyof T; value: T[keyof T] }
  | { type: 'reset' };

export function useReducerForm<T extends Record<string, unknown>>(initial: T) {
  const [values, dispatch] = useReducer((state: T, action: Action<T>): T => {
    switch (action.type) {
      case 'set': return { ...state, [action.key]: action.value };
      case 'reset': return initial;
      default: return state;
    }
  }, initial);

  const setField = (key: keyof T, value: T[keyof T]) =>
    dispatch({ type: 'set', key, value });

  const reset = () => dispatch({ type: 'reset' });

  return { values, setField, reset };
}
